import freeCatalog from "resources/cosmetics/cosmetics.json";
import { Cosmetics, CosmeticsSchema } from "./CosmeticSchemas";

/**
 * This fork's own cosmetics catalog (resources/cosmetics/cosmetics.json,
 * generated by scripts/generate-free-cosmetics.py). It replaces the paid
 * catalog from the closed-source API: every item in it is free.
 */
export const FREE_COSMETICS: Cosmetics = CosmeticsSchema.parse(freeCatalog);

/**
 * Wildcard flares every player holds, so every catalog item is owned by
 * everyone — on the client (store/inventory) and on the server (join check).
 */
export const FREE_FLARES: readonly string[] = [
  "pattern:*",
  "skin:*",
  "effect:*",
  "flag:*",
  "crown:*",
];

/** A player's flares plus the free wildcards. */
export function withFreeFlares(
  flares: readonly string[] | undefined,
): string[] {
  return [...FREE_FLARES, ...(flares ?? [])];
}
